#!/usr/bin/env node
/*
 * Deterministic scorer for council eval runs. It scores; it does not run.
 *
 * Council runs are costly and non-deterministic, so they are generated by the maintainer
 * in Claude Code (see eval/README.md) and dropped into a runs directory. This script reads
 * that directory, measures the same things for every arm, and compares arms. The same
 * input always gives the same output, which is what lets a baseline recorded on v2.2.0 be
 * compared with a v3 run months later.
 *
 * Layout:
 *   <runs>/<arm>/arm.json                      {"arm": "v3", "version": "3.0.0", "verify": "<pasted `verify` output>"}
 *   <runs>/<arm>/<case-id>/council.json        the journal record for the council run (one JSON object)
 *   <runs>/<arm>/<case-id>/seats/<persona>-<n>.md   seat micro-eval returns (optional)
 *
 * Usage:
 *   node scripts/eval-council.js <runs-dir> [--cases eval/cases] [--json]
 *
 * What it measures, per arm:
 *   - block completeness and atomic CONDITIONs (<= 25 words, one requirement)
 *   - the offensive-security gap: the other seats' mean PROBABILITY minus offensive-security's.
 *     Under v2 it was the seat that scored lowest in 5 of 10 runs, because it read its number
 *     as "no breach afterwards".
 *   - how seats define their number (micro-evals carry a PROBABILITY MEANS line)
 *   - stance mix: share of conditional-go, and whether any seat ever says no-go
 *   - convergence: recomputed from the acceptance matrix where present, and checked
 *     against the recorded value
 *   - case expectations from eval/cases/<id>.json (canary direction, preferred option,
 *     probability floors, action-plan content)
 * A run that cannot be scored honestly (wrong personas loaded, seats missing, protocol not
 * the arm's) is listed as invalid with its reason and kept out of every metric.
 */
'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const JOURNAL_JS = path.join(ROOT, '.claude', 'skills', 'infosec-council', 'journal.js');
const { convergence } = require(JOURNAL_JS);

const STOP_STANCES = ['no-go', 'defer', 'reframe'];
const GO_STANCES = ['go', 'conditional-go'];
const CONDITION_MAX_WORDS = 25;
// Heuristic, and labelled as one in the output: a condition that joins requirements with
// "and", "as well as", "plus", a semicolon or "&" is treated as compound.
const COMPOUND = /\b(and|as well as|plus)\b|;|&/i;
// Negated forms ("whether or not an incident", "incident or not") are the v3 definition
// itself, so they are stripped before the outcome test.
const NEGATED = /whether or not (a |an )?(breach|incident)[^,.;]*|(breach|incident) or not|regardless of (a |an )?(breach|incident)|a quiet year[^,.;]*/gi;
const OUTCOME_WORDS = /\b(no|without( a| an)?|zero|avoid(s|ing)?( a| an)?)\s+(breach|incident|compromise|loss)|nothing bad|surviv|hold(s)? up|goes wrong|does ?n.t (fail|go wrong)/i;
const DECISION_WORDS = /would still (choose|pick|make)|still (be )?(the right|chosen)|with hindsight|in hindsight|over the alternatives|right (call|choice)|choice (holds|was right)/i;

function readJSON(f) { return JSON.parse(fs.readFileSync(f, 'utf8')); }
function words(s) { return (String(s || '').trim().match(/\S+/g) || []).length; }
function mean(xs) { return xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null; }
function round(x, d) { return x == null ? null : +x.toFixed(d == null ? 1 : d); }
function choiceKey(s) {
  const m = String(s || '').match(/^\s*(?:option\s*)?([A-Za-z0-9]+)\b/i);
  return m ? m[1].toUpperCase() : null;
}

function conditionQuality(c) {
  if (typeof c !== 'string' || !c.trim()) return null;
  return { words: words(c), long: words(c) > CONDITION_MAX_WORDS, compound: COMPOUND.test(c) };
}

// Parse a seat's text return. Only the block lines are read; the analysis above them is
// the seat's business and is not scored here.
function parseSeat(text) {
  // The LAST match wins: the block closes the return, and a prose line in the analysis
  // such as "First: ..." must not stand in for it.
  const line = function (key) {
    const all = Array.from(text.matchAll(new RegExp('^\\s*\\**' + key + '\\**\\s*:\\s*\\**\\s*(.+)$', 'gim')));
    return all.length ? all[all.length - 1][1].trim() : null;
  };
  const prob = line('PROBABILITY');
  const p = prob && prob.match(/(\d{1,3})/);
  const meaning = line('PROBABILITY MEANS');
  let meaningClass = null;
  if (meaning) {
    meaningClass = OUTCOME_WORDS.test(meaning.replace(NEGATED, '')) ? 'outcome-contaminated'
      : DECISION_WORDS.test(meaning) ? 'decision-quality' : 'unclear';
  }
  return {
    stance: line('STANCE'), choice: line('CHOICE'), first: line('FIRST'), not_now: line('NOT NOW'),
    condition: line('CONDITION'),
    probability: p ? Math.min(100, +p[1]) : null,
    wrote_confidence: line('CONFIDENCE') != null,
    meaning, meaningClass
  };
}

function scoreCouncil(rec, kase, armProtocol) {
  const invalid = [];
  const members = Array.isArray(rec.members) ? rec.members : [];
  const mode = rec.mode || 'standard';
  if (!rec.question) invalid.push('record has no question');
  if (mode !== 'quick' && members.length !== 7) invalid.push('expected 7 seats, found ' + members.length);
  if (mode === 'quick' && members.length !== 3) invalid.push('expected 3 seats in quick, found ' + members.length);
  const missing = members.filter(m => m && m.stance === 'missing').length;
  if (missing > 1) invalid.push(missing + ' seats missing; one is tolerated, more is a broken run');
  if (armProtocol === 'v3' && rec.protocol !== '3.0.0') invalid.push('arm is v3 but the record carries protocol ' + JSON.stringify(rec.protocol));
  if (armProtocol === 'baseline' && rec.protocol === '3.0.0') invalid.push('arm is baseline but the record was written by v3');

  const present = members.filter(m => m && m.stance !== 'missing');
  const conds = present.map(m => conditionQuality(m.condition)).filter(Boolean);
  const off = present.find(m => m.name === 'offensive-security');
  const others = present.filter(m => m.name !== 'offensive-security' && typeof m.probability === 'number').map(m => m.probability);
  const stop = present.filter(m => STOP_STANCES.includes(m.stance)).length;
  const go = present.filter(m => GO_STANCES.includes(m.stance)).length;

  const out = {
    case: kase ? kase.id : null, sha: rec.sha || null, mode, invalid,
    seats: members.length, missing,
    conditions: conds.length,
    conditions_long: conds.filter(c => c.long).length,
    conditions_compound: conds.filter(c => c.compound).length,
    conditions_nonatomic: conds.filter(c => c.long || c.compound).length,
    offsec_gap: off && typeof off.probability === 'number' && others.length ? round(mean(others) - off.probability) : null,
    share_conditional_go: present.length ? round(present.filter(m => m.stance === 'conditional-go').length / present.length, 3) : null,
    no_go_seats: present.filter(m => m.stance === 'no-go').length,
    action_plan_items: Array.isArray(rec.action_plan) ? rec.action_plan.length : null,
    alternatives: Array.isArray(rec.alternatives) ? rec.alternatives.length : 0,
    converged_recorded: rec.converged || null,
    converged_consistent: null,
    expectations: []
  };

  if (rec.acceptance && mode !== 'quick') {
    const c = convergence({ members, acceptance: rec.acceptance, question_type: rec.question_type });
    out.converged_computed = c.outcome;
    out.converged_consistent = rec.converged == null ? null : c.allowed.includes(rec.converged);
  }

  const ex = (kase && kase.expect) || {};
  const expect = function (name, pass, detail) { out.expectations.push({ name, pass: !!pass, detail }); };
  if (ex.majority === 'stop') expect('panel stops it', stop > go, stop + ' stop vs ' + go + ' go');
  if (ex.majority === 'go') expect('panel backs it', go > stop, go + ' go vs ' + stop + ' stop');
  let aligned = present;
  if (ex.choice) {
    aligned = present.filter(m => choiceKey(m.choice) === String(ex.choice).toUpperCase());
    expect('majority picks ' + ex.choice, aligned.length > present.length / 2, aligned.length + ' of ' + present.length);
  } else if (ex.majority === 'go') {
    aligned = present.filter(m => GO_STANCES.includes(m.stance));
  }
  if (typeof ex.min_probability_aligned === 'number') {
    const mp = mean(aligned.filter(m => typeof m.probability === 'number').map(m => m.probability));
    expect('aligned seats rate it >= ' + ex.min_probability_aligned, mp != null && mp >= ex.min_probability_aligned, 'mean ' + round(mp));
  }
  if (typeof ex.offsec_min_probability === 'number') {
    const o = aligned.find(m => m.name === 'offensive-security');
    if (o) expect('offensive-security, aligned, rates it >= ' + ex.offsec_min_probability,
      typeof o.probability === 'number' && o.probability >= ex.offsec_min_probability, 'offensive-security ' + o.probability);
    else expect('offensive-security is aligned', false, 'it chose otherwise or is missing');
  }
  for (const pat of (ex.action_plan_matches || [])) {
    const re = new RegExp(pat, 'i');
    const hit = (rec.action_plan || []).some(a => a && re.test(String(a.action || '')));
    expect('action plan carries /' + pat + '/', hit, hit ? 'found' : 'absent');
  }
  for (const seat of (ex.seat_present || [])) {
    expect(seat + ' seated', present.some(m => m.name === seat), '');
  }
  return out;
}

function scoreSeats(dir) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir).filter(f => f.endsWith('.md')).sort().map(function (f) {
    const persona = f.replace(/-\d+\.md$/, '').replace(/\.md$/, '');
    const parsed = parseSeat(fs.readFileSync(path.join(dir, f), 'utf8'));
    const cq = conditionQuality(parsed.condition);
    return Object.assign({ file: f, persona, condition_long: cq ? cq.long : null, condition_compound: cq ? cq.compound : null,
      complete: parsed.probability != null && (parsed.stance || parsed.choice || parsed.first) != null }, parsed);
  });
}

function aggregate(armName, councils, seats) {
  const valid = councils.filter(c => !c.invalid.length);
  const all = valid.reduce((a, c) => a.concat(c.expectations), []);
  const conds = valid.reduce((a, c) => a + c.conditions, 0);
  const seatConds = seats.filter(s => s.condition_long != null);
  const meanings = seats.filter(s => s.meaningClass);
  const byPersona = {};
  for (const s of seats) if (s.probability != null) (byPersona[s.persona] = byPersona[s.persona] || []).push(s.probability);
  const offSeat = byPersona['offensive-security'];
  const otherSeat = Object.keys(byPersona).filter(k => k !== 'offensive-security').reduce((a, k) => a.concat(byPersona[k]), []);
  return {
    arm: armName,
    council_runs: councils.length, valid_runs: valid.length,
    invalid_runs: councils.filter(c => c.invalid.length).map(c => ({ case: c.case, reasons: c.invalid })),
    expectations_passed: all.filter(e => e.pass).length, expectations_total: all.length,
    atomic_condition_rate: conds ? round(1 - valid.reduce((a, c) => a + c.conditions_nonatomic, 0) / conds, 3) : null,
    mean_offsec_gap: round(mean(valid.map(c => c.offsec_gap).filter(x => x != null))),
    mean_share_conditional_go: round(mean(valid.map(c => c.share_conditional_go).filter(x => x != null)), 3),
    no_go_seats_total: valid.reduce((a, c) => a + c.no_go_seats, 0),
    converged_inconsistent: valid.filter(c => c.converged_consistent === false).length,
    seat_returns: seats.length,
    seat_block_complete_rate: seats.length ? round(seats.filter(s => s.complete).length / seats.length, 3) : null,
    seat_atomic_condition_rate: seatConds.length ? round(seatConds.filter(s => !s.condition_long && !s.condition_compound).length / seatConds.length, 3) : null,
    seat_wrote_confidence_word: seats.filter(s => s.wrote_confidence).length,
    seat_meaning: meanings.length ? {
      decision_quality: meanings.filter(s => s.meaningClass === 'decision-quality').length,
      outcome_contaminated: meanings.filter(s => s.meaningClass === 'outcome-contaminated').length,
      unclear: meanings.filter(s => s.meaningClass === 'unclear').length,
      note: 'keyword classification of the PROBABILITY MEANS line; read the unclear ones by hand'
    } : null,
    seat_offsec_gap: offSeat && otherSeat.length ? round(mean(otherSeat) - mean(offSeat)) : null
  };
}

function scoreArm(armDir, cases) {
  const armFile = path.join(armDir, 'arm.json');
  const meta = fs.existsSync(armFile) ? readJSON(armFile) : {};
  const name = meta.arm || path.basename(armDir);
  const protocol = /^3\./.test(String(meta.version || '')) ? 'v3' : (meta.version ? 'baseline' : null);
  const armInvalid = [];
  if (!meta.version) armInvalid.push('arm.json is missing "version"; cannot tell which protocol produced these runs');
  // A v3 arm run with v2 persona copies on disk is a v2 run wearing a v3 label: the
  // stale persona outranks the plugin's and restores both the old definition and every tool.
  if (protocol === 'v3' && typeof meta.verify === 'string' && /stale council persona/i.test(meta.verify)) {
    armInvalid.push('verify reported stale council personas; the seats were not the v3 seats');
  }
  if (protocol === 'v3' && typeof meta.verify !== 'string') armInvalid.push('arm.json carries no `verify` output, so the loaded personas are unproven');

  const councils = [], seats = [];
  for (const caseId of fs.readdirSync(armDir).filter(d => fs.statSync(path.join(armDir, d)).isDirectory()).sort()) {
    const kase = cases[caseId] || null;
    const cf = path.join(armDir, caseId, 'council.json');
    if (fs.existsSync(cf)) {
      let rec;
      try { rec = readJSON(cf); } catch (e) { councils.push({ case: caseId, invalid: ['council.json is not valid JSON'], expectations: [] }); continue; }
      const sc = scoreCouncil(rec, kase || { id: caseId }, protocol);
      if (!kase) sc.invalid.push('no case definition eval/cases/' + caseId + '.json');
      sc.invalid = armInvalid.concat(sc.invalid);
      councils.push(sc);
    }
    if (!armInvalid.length) seats.push.apply(seats, scoreSeats(path.join(armDir, caseId, 'seats')).map(s => Object.assign({ case: caseId }, s)));
  }
  return { summary: aggregate(name, councils, seats), councils, seats, arm_invalid: armInvalid };
}

function loadCases(dir) {
  const out = {};
  if (!fs.existsSync(dir)) return out;
  for (const f of fs.readdirSync(dir).filter(f => f.endsWith('.json'))) {
    const c = readJSON(path.join(dir, f));
    out[c.id || f.replace(/\.json$/, '')] = c;
  }
  return out;
}

function render(result) {
  const arms = result.arms.map(a => a.summary);
  const rows = [
    ['valid council runs', a => a.valid_runs + ' of ' + a.council_runs],
    ['case expectations passed', a => a.expectations_passed + ' of ' + a.expectations_total],
    ['atomic CONDITION rate (council)', a => a.atomic_condition_rate],
    ['offensive-security gap (council, points)', a => a.mean_offsec_gap],
    ['share conditional-go', a => a.mean_share_conditional_go],
    ['no-go seat positions', a => a.no_go_seats_total],
    ['converged contradicts matrix', a => a.converged_inconsistent],
    ['seat returns scored', a => a.seat_returns],
    ['seat block complete rate', a => a.seat_block_complete_rate],
    ['seat atomic CONDITION rate', a => a.seat_atomic_condition_rate],
    ['seat wrote a CONFIDENCE word', a => a.seat_wrote_confidence_word],
    ['seat PROBABILITY read as decision quality', a => a.seat_meaning ? a.seat_meaning.decision_quality + ' of ' + (a.seat_meaning.decision_quality + a.seat_meaning.outcome_contaminated + a.seat_meaning.unclear) : null],
    ['seat PROBABILITY read as "no incident"', a => a.seat_meaning ? a.seat_meaning.outcome_contaminated : null],
    ['offensive-security gap (seats, points)', a => a.seat_offsec_gap]
  ];
  const lines = ['| Metric | ' + arms.map(a => a.arm).join(' | ') + ' |', '|---|' + arms.map(() => '---|').join('')];
  for (const [label, fn] of rows) lines.push('| ' + label + ' | ' + arms.map(a => { const v = fn(a); return v == null ? 'n/a' : String(v); }).join(' | ') + ' |');
  for (const arm of result.arms) for (const r of arm.arm_invalid) lines.push('\narm invalid (' + arm.summary.arm + '): ' + r);
  for (const a of arms) for (const inv of a.invalid_runs) lines.push('\ninvalid (' + a.arm + ', ' + inv.case + '): ' + inv.reasons.join('; '));
  for (const arm of result.arms) for (const c of arm.councils) for (const e of (c.expectations || [])) {
    if (!e.pass) lines.push('expectation failed (' + arm.summary.arm + ', ' + c.case + '): ' + e.name + (e.detail ? ' [' + e.detail + ']' : ''));
  }
  return lines.join('\n');
}

function main() {
  const args = process.argv.slice(2);
  const ci0 = args.indexOf('--cases');
  const runsDir = args.find((a, i) => !a.startsWith('--') && !(ci0 >= 0 && i === ci0 + 1));
  if (!runsDir) {
    console.error('usage: node scripts/eval-council.js <runs-dir> [--cases eval/cases] [--json]');
    process.exit(2);
  }
  const ci = args.indexOf('--cases');
  const cases = loadCases(ci >= 0 ? args[ci + 1] : path.join(ROOT, 'eval', 'cases'));
  const arms = fs.readdirSync(runsDir).filter(d => fs.statSync(path.join(runsDir, d)).isDirectory()).sort()
    .map(d => scoreArm(path.join(runsDir, d), cases));
  const result = { arms };
  if (args.includes('--json')) console.log(JSON.stringify(result, null, 2));
  else console.log(render(result));
}

if (require.main === module) main();
module.exports = { parseSeat, scoreCouncil, scoreArm, loadCases, conditionQuality };
